import { test, expect } from '@playwright/test';

test.describe('Image Clipboard Upload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should paste image from clipboard into upload area', async ({ page, context }) => {
    // Create a simple 1x1 PNG image as base64
    const pngBase64 = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==';
    const pngBuffer = Buffer.from(pngBase64, 'base64');

    // Grant clipboard permissions
    await context.grantPermissions(['clipboard-read', 'clipboard-write']);

    // Set clipboard content with image
    await page.evaluate(async (imageData) => {
      const blob = new Blob([new Uint8Array(imageData)], { type: 'image/png' });
      const item = new ClipboardItem({ 'image/png': blob });
      await navigator.clipboard.write([item]);
    }, Array.from(pngBuffer));

    // Find the upload area
    const uploadArea = page.getByRole('region', { name: /upload/i });

    // Paste the image
    await uploadArea.focus();
    await page.keyboard.press('Control+V');

    // Verify image was uploaded
    const uploadedImage = page.getByRole('img', { name: /uploaded/i });
    await expect(uploadedImage).toBeVisible();
  });

  test('should display uploaded image in preview', async ({ page, context }) => {
    // Create a simple 1x1 PNG image as base64
    const pngBase64 = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==';
    const pngBuffer = Buffer.from(pngBase64, 'base64');

    // Grant clipboard permissions
    await context.grantPermissions(['clipboard-read', 'clipboard-write']);

    // Set clipboard content with image
    await page.evaluate(async (imageData) => {
      const blob = new Blob([new Uint8Array(imageData)], { type: 'image/png' });
      const item = new ClipboardItem({ 'image/png': blob });
      await navigator.clipboard.write([item]);
    }, Array.from(pngBuffer));

    // Find and interact with upload area
    const uploadArea = page.getByRole('region', { name: /upload/i });
    await uploadArea.focus();
    await page.keyboard.press('Control+V');

    // Verify preview container is visible
    const previewContainer = page.getByRole('region', { name: /preview/i });
    await expect(previewContainer).toBeVisible();

    // Verify image dimensions are displayed
    const imageDimensions = page.getByText(/\d+x\d+/);
    await expect(imageDimensions).toBeVisible();
  });

  test('should handle paste of non-image content gracefully', async ({ page, context }) => {
    // Grant clipboard permissions
    await context.grantPermissions(['clipboard-read', 'clipboard-write']);

    // Set clipboard content with text instead of image
    await page.evaluate(async () => {
      const item = new ClipboardItem({ 'text/plain': new Blob(['not an image'], { type: 'text/plain' }) });
      await navigator.clipboard.write([item]);
    });

    // Find and interact with upload area
    const uploadArea = page.getByRole('region', { name: /upload/i });
    await uploadArea.focus();
    await page.keyboard.press('Control+V');

    // Verify error message is displayed
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText(/invalid|image|format/i);
  });
});
